]

const PLATFORM_META = {
  amazon: {
    key: 'amazon',
    label: 'Amazon',
    focus: '销售异常、账号健康、前台巡检 12 项',
    schedule: '销售异常 每日 07:00 · 账号异常 05:30 起每 8h',
