            @click="openCreate"
          >
            新建异常任务
          </button>
          <button
            v-if="
              activeTab === 'tasks' ||
              activeTab === 'dashboard' ||
              activeTab === 'metrics' ||
              activeTab.endsWith('-overview') ||
              activeTab === 'amz-anomaly' ||
              activeTab === 'temu-health'
            "
            class="btn"
            :disabled="loading"
            @click="refreshActive"
          >
            刷新
          </button>
          <button
            v-if="activeTab === 'shops'"
            class="btn"
            :disabled="loading"
            @click="loadShops"
          >
            刷新
          </button>
        </div>
      </header>

      <div class="main-body">
        <div v-if="error" class="error" style="margin-bottom: 12px">{{ error }}</div>

        <!-- 仪表盘 -->
        <section v-show="activeTab === 'metrics'">
          <div class="grid-stats">
            <div class="stat accent">
              <div class="label">异常任务总数</div>
              <div class="value">{{ stats.total }}</div>
            </div>
            <div class="stat">
              <div class="label">待处理</div>
              <div class="value">{{ stats.open }}</div>
            </div>
            <div class="stat">
              <div class="label">进行中</div>
              <div class="value">{{ stats.doing }}</div>
            </div>
            <div class="stat">
              <div class="label">已闭环（本页）</div>
              <div class="value">{{ stats.resolved }}</div>
            </div>
          </div>

          <div class="dash-grid">
            <div class="card">
              <h2>任务状态分布</h2>
              <div class="bar-list">
                <div v-for="row in statusBars" :key="row.key" class="bar-row">
                  <div class="bar-meta">
                    <span>{{ row.label }}</span>
                    <span class="mono">{{ row.count }} · {{ row.pct }}%</span>
                  </div>
                  <div class="bar-track">
                    <div class="bar-fill" :style="{ width: row.pct + '%', background: row.color }" />
                  </div>
                </div>
              </div>
            </div>
            <div class="card">
              <h2>分平台异常量（本页）</h2>
              <div class="bar-list">
                <div v-for="row in platformTaskStats" :key="row.platform" class="bar-row">
                  <div class="bar-meta">
                    <span class="platform-tag">{{ row.platform }}</span>
                    <span class="mono">{{ row.count }}</span>
                  </div>
                  <div class="bar-track">
                    <div class="bar-fill platform" :style="{ width: row.pct + '%' }" />
