                    <td class="muted">{{ fmtTime(t.updated_at) }}</td>
                    <td>
                      <div v-if="t.status !== 'resolved' && t.status !== 'cancelled'" class="actions">
                        <button class="btn btn-ghost" @click="openProgress(t)">进度</button>
                        <button class="btn btn-danger" @click="openResolve(t)">闭环</button>
                      </div>
                      <span v-else class="muted">—</span>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        </section>

        <!-- Temu 发货 -->
        <section v-show="activeTab === 'temu-shipping'">
          <div class="grid-stats">
            <div class="stat accent"><div class="label">授权店铺</div><div class="value">{{ shippingShops.length }}</div></div>
            <div class="stat"><div class="label">默认仓</div><div class="value" style="font-size: 18px">UK WMS</div></div>
            <div class="stat"><div class="label">ERP</div><div class="value" style="font-size: 18px">赛狐</div></div>
            <div class="stat"><div class="label">链路状态</div><div class="value" style="font-size: 18px; color: var(--warn)">独立运行</div></div>
          </div>
          <div class="card">
            <h2>发货流水线</h2>
            <div class="pipeline">
              <div v-for="s in shippingPipeline" :key="s.step" class="pipe-step">
                <div class="pipe-num">{{ s.step }}</div>
                <div>
                  <div class="pipe-title">{{ s.title }}</div>
                  <div class="muted">{{ s.desc }}</div>
                </div>
              </div>
            </div>
          </div>
          <div class="card">
            <div class="card-head">
              <h2>授权店铺（海外仓）</h2>
              <span class="muted">发货桥暂独立 · 后续并入中心</span>
            </div>
            <div class="table-wrap">
              <table>
                <thead>
                  <tr><th>店铺</th><th>平台</th><th>履约仓</th><th>说明</th></tr>
                </thead>
                <tbody>
                  <tr v-for="s in shippingShops" :key="s.name">
                    <td>{{ s.name }}</td>
                    <td>{{ s.platform }}</td>
                    <td>{{ s.warehouse }}</td>
                    <td class="muted">赛狐授权 · 自动出库</td>
                  </tr>
                </tbody>
              </table>
            </div>
            <ul class="hint-list" style="margin-top: 14px">
              <li>现有资产：<code>E:\project\海外仓</code></li>
              <li>Phase1：赛狐客户端 → <code>collectors/sellfox-worker</code></li>
            </ul>
          </div>
        </section>

        <!-- Temu 插件 -->
        <section v-show="activeTab === 'temu-plugin'">
          <div class="plugin-grid">
            <div
              v-for="p in plugins.filter((x) => x.platformKey === 'temu' || x.platformKey === 'common')"
              :key="p.id"
              class="card plugin-card"
            >
              <div class="plugin-head">
                <div>
                  <div class="plugin-name">{{ p.name }}</div>
                  <div class="muted">{{ p.kind }}</div>
                </div>
                <span class="badge-status" :class="p.statusClass">{{ p.status }}</span>
              </div>
              <p class="plugin-desc">{{ p.desc }}</p>
              <div class="mono muted">{{ p.path }}</div>
            </div>
          </div>
        </section>
      </div>
    </div>

    <div v-if="drawer.open" class="drawer-mask" @click.self="closeDrawer">
      <div class="drawer">
        <h2 style="margin-top: 0">
          <template v-if="drawer.mode === 'create'">新建异常任务</template>
          <template v-else-if="drawer.mode === 'progress'">更新进度</template>
          <template v-else>闭环异常任务</template>
        </h2>

        <div v-if="drawer.mode === 'create'" class="stack">
          <label class="field">
            平台
            <select v-model="createForm.platform">
              <option value="tiktok">tiktok</option>
              <option value="amazon">amazon</option>
              <option value="temu">temu</option>
            </select>
          </label>
          <label class="field">
            异常类型
            <input v-model="createForm.anomaly_type" placeholder="如 low_roi / listing_prime" />
          </label>
          <label class="field">
            业务ID
            <input v-model="createForm.biz_id" placeholder="ASIN / 商品ID / 系列名" />
          </label>
          <label class="field">
            标题
            <input v-model="createForm.title" placeholder="任务标题" />
          </label>
          <label class="field">
            备注
            <textarea v-model="createForm.progress_note" placeholder="可选" />
          </label>
        </div>

        <div v-else class="stack">
          <div class="muted mono">{{ drawer.task?.dedupe_key }}</div>
          <div><strong>{{ drawer.task?.title }}</strong></div>
          <label class="field">
            说明
            <textarea
              v-model="drawer.note"
              :placeholder="drawer.mode === 'resolve' ? '闭环说明' : '今日处理进度'"
            />
          </label>
        </div>

        <div class="actions" style="margin-top: 16px; justify-content: flex-end">
          <button class="btn" @click="closeDrawer">取消</button>
          <button class="btn btn-primary" :disabled="loading" @click="submitDrawer">
            {{ loading ? '提交中…' : '确定' }}
          </button>
        </div>
      </div>
    </div>
  </div>
</template>
"}

